(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*15;
  const w1y = Math.cos(y*0.015-t*0.22)*20 + Math.sin(x*0.013+t*0.28)*15;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*10 + Math.cos(sy*0.02-t*0.3)*8;
  const w2y = Math.cos(sy*0.025-t*0.35)*10 + Math.sin(sx*0.022+t*0.45)*8;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*55, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*65, 0.05, 2.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((wx-sX)**2+(wy-sY)**2);
    const d2 = Math.sqrt((sx-sX*0.5+cx*0.5)**2+(sy-sY*0.5+cy*0.5)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d2*f*1.3-t*sp*0.8+2.0);
    iS2 += Math.sin(d2*f*0.5+t*sp*0.4+3.0);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8, inh2=iS2/8;
  const bg = (Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2
    + Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2
    + Math.sin(wx*0.08+wy*0.06+t*1.8)*0.15;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2), ang=Math.atan2(wy-cy,wx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.03-ang*5+t*0.9)*0.5)*0.35;
  const moire = Math.sin(dist*0.08)*Math.sin(ang*6+t)*0.3;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2 = Math.tanh((act2-inh2*0.6+moire)*1.8);
  const cell = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15)+Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.sin(wx*0.22+t*0.3)*Math.cos(wy*0.18-t*0.4))*1.2)*0.2;
  const combined = reaction*0.45+reaction2*0.25+cell*0.2+cell2*0.1;
  const glow = Math.exp(-Math.abs(combined)*1.5)*0.4;
  const v = combined*0.5+0.5+glow*0.15;
  const pal = [[6,12,52],[12,45,85],[18,95,120],[25,150,135],[180,175,70],
    [215,130,65],[195,75,75],[120,35,65],[55,18,55],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.3;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction2)>0.6?1.08:1.0;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
